function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // background rice bowl
  ctx.fillStyle = '#fffcf4';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.fill();

  // spoon
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2);
  ctx.lineTo(W/2 - 50, H/2 - 50);
  ctx.stroke();

  // people eating
  ctx.fillStyle = 'black';
  for (let i = 0; i < 5; i++) {
    let x = W/2 + Math.sin(t + i) * 100;
    let y = H/2 + Math.cos(t + i) * 50;
    ctx.beginPath();
    ctx.arc(x, y, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(x, y + 10);
    ctx.lineTo(x, y + 50);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 20);
    ctx.lineTo(x - 10, y + 30);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y + 20);
    ctx.lineTo(x + 10, y + 30);
    ctx.stroke();
  }

  // rice grains
  ctx.fillStyle = '#fffcf4';
  for (let i = 0; i < 20; i++) {
    let x = W/2 + Math.sin(t + i * 2) * 50;
    let y = H/2 + Math.cos(t + i * 2) * 20;
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, 2 * Math.PI);
    ctx.fill();
  }

  ctx.restore();
}
